115	extern "C" auto sc_main(int argc, char* argv[]) -> int
116	try {
117	  spdlog::set_default_logger(spdlog::stderr_color_mt("stderr_logger"));
118	  spdlog::set_pattern("[%^%l%$] %v");
119	
120	  if (argc < 2) {
121	    std::fprintf(stderr, "usage: %s <elf>\n", argv[0]);
122	    return EXIT_FAILURE;
123	  }
124	  auto broker = cci_utils::broker{"global_broker"};
125	  cci::cci_register_broker(broker);
126	  return run_smoke<VSIM_CPU_INTERFACE_CLASS>(argv[1]);
127	} catch (const std::exception& e) {
128	  spdlog::error("dmi_smoke FAIL: exception: {}", e.what());
129	  return 99;
